fn trace(a: Vec<Vec<f32>>, offset: i32) -> f32 {
    let mut sum = 0.0;
    for (i, row) in a.into_iter().enumerate() {
        // compute the shifted column index
        let j = i as i32 + offset;
        // only proceed if j is non-negative
        if j >= 0 {
            let j = j as usize;
            // check that this row actually has a column j
            if j < row.len() {
                sum += row[j];
            }
        }
    }
    sum
}

